const fs = require('fs');
const path = require('path');

function scanTools(dir) {
    const tools = [];
    const files = fs.readdirSync(dir).filter(f => f.endsWith('.js'));
    
    for (const file of files) {
const content = fs.readFileSync(path.join(dir, file), 'utf8');
        const lines = content.split('\n');
        
        // Extract description: first /** */ block or // comment
        let description = '';
        let inDoc = false;
        for (const line of lines) {
            if (line.includes('/**')) { inDoc = true; continue; }
            if (line.includes('*/')) { inDoc = false; break; }
            if (inDoc && line.trim().startsWith('*') && !description) {
                description = line.trim().substring(1).trim().substring(0, 80);
            }
            if (!inDoc && line.trim().startsWith('//') && !description) {
                description = line.trim().substring(2).trim().substring(0, 80);
                break;
            }
        }
        
        // Extract exports
        const exports = [];
        const exportMatch = content.match(/module\.exports\s*=\s*{([^}]+)}/);
        if (exportMatch) {
            exports.push(...exportMatch[1].split(',').map(e => e.trim().split(':')[0].trim()));
        }
        
        tools.push({ file, description, exports });
    }
    
    return tools;
}

function main() {
    const tools = scanTools(path.join(__dirname));
    const args = process.argv.slice(2);
    
    if (args[0] === '--list') {
        console.log(JSON.stringify(tools, null, 2));
    } else if (args[0] === '--search' && args[1]) {
        const keyword = args[1].toLowerCase();
        const filtered = tools.filter(t => 
            t.description.toLowerCase().includes(keyword) || 
            t.exports.some(e => e.toLowerCase().includes(keyword))
        );
        console.log(JSON.stringify(filtered, null, 2));
    }
}

if (require.main === module) {
    main();
}

